import type { Lang } from '@/lib/i18n'

export type PolicyPart =
  | { type: 'p'; text: string }
  | { type: 'ul'; items: string[] }
  | { type: 'table' }
  | { type: 'officer' }

export type PrivacyPolicyDoc = {
  title: string
  intro: string
  articleLabel: (n: number) => string
  articles: { title: string; parts: PolicyPart[] }[]
  tableHead: string[]
  vercel: string[]
  google: string[]
  officerName: string
  officerRole: string
  labelName: string
  labelPhone: string
  labelEmail: string
}

const art = (n: number, word: string) => `${word} ${n}`

function doc(
  title: string,
  intro: string,
  label: (n: number) => string,
  articles: PrivacyPolicyDoc['articles'],
  tableHead: string[],
  vercel: string[],
  google: string[],
  officer: Pick<PrivacyPolicyDoc, 'officerName' | 'officerRole' | 'labelName' | 'labelPhone' | 'labelEmail'>,
): PrivacyPolicyDoc {
  return { title, intro, articleLabel: label, articles, tableHead, vercel, google, ...officer }
}

