const en = doc(
  'Privacy Policy',
  'The Sejong Korean Language and Culture Center (세종국어문화원, the “Center”) operates the Sejong Speech Sounds website (https://www.sejongsound.org, the “Site”). Under Article 30 of the Personal Information Protection Act of the Republic of Korea, the Center adopts and publishes this policy so that personal data is protected and related complaints are handled promptly.',
  (n) => art(n, 'Article'),
  [
    { title: 'Purpose of processing', parts: [{ type: 'p', text: 'Personal data is processed to review and reply to messages sent through the Site’s contact form (research collaboration, data access, conferences and seminars, graduate study, and general inquiries). It is not used for any other purpose. If the purpose changes, separate consent is obtained under Article 18 of the Act.' }] },
    { title: 'Personal data we process', parts: [{ type: 'ul', items: ['Required: name, email address', 'Optional: affiliation', 'The inquiry type and message are received so that we can reply. Please do not include a resident registration number or other sensitive information.', 'In operating the service, access logs (IP address, time, browser) may remain for a time in the hosting provider’s logs. To prevent misuse of the form (spam), the IP address is kept in server memory for at most one hour and is not stored separately.'] }, { type: 'p', text: 'The Site does not offer membership, and it does not use analytics tools or advertising cookies.' }] },
    { title: 'Retention', parts: [{ type: 'p', text: 'Personal data from the contact form is not stored on the Site’s server. It is sent to the Center’s email ({email}), kept for one year after the inquiry is resolved, and then destroyed. If another statute requires retention, it is kept for that period.' }] },
    { title: 'Provision to third parties', parts: [{ type: 'p', text: 'The Center processes personal data only within the purpose in Article 1. It is not provided to a third party except with the data subject’s consent or where Articles 17 and 18 of the Act otherwise allow it.' }] },
    { title: 'Processors and overseas transfer', parts: [{ type: 'p', text: 'To operate the Site, the Center entrusts processing as follows. Because the processors’ servers are outside Korea, personal data is transferred overseas.' }, { type: 'table' }, { type: 'p', text: 'If you do not want this overseas transfer, contact us by email ({email}) or phone ({phone}) instead of the form.' }] },
    { title: 'Destruction', parts: [{ type: 'p', text: 'Personal data is destroyed without delay when the retention period ends or the purpose is achieved. Electronic files are deleted so that they cannot be restored. Paper documents are shredded or incinerated.' }] },
    { title: 'Rights of the data subject', parts: [{ type: 'p', text: 'You may at any time ask the Center for access, correction or deletion, suspension of processing, or withdrawal of consent. These rights may be exercised by writing, phone, or email using the contact in Article 10, and the Center will act without delay. A legal representative or an authorized agent may exercise them as well.' }] },
    { title: 'Security measures', parts: [{ type: 'ul', items: ['Encryption in transit: all communication with the Site uses HTTPS.', 'Minimal storage: personal data from the contact form is not stored on the Site’s server.', 'Access control: administrative functions are available only to authenticated administrators.', 'Abuse prevention: an automated-input check and a limit on how often the form may be sent.'] }] },
    { title: 'Automatic collection, and how to refuse it', parts: [{ type: 'p', text: 'The Site does not use cookies that identify or track visitors. The chosen language, display theme, and saved translation results are kept in the browser’s storage (localStorage) so they can be used on the next visit. That storage does not identify a person. You can delete it at any time in the browser’s site-data settings.' }] },
    { title: 'Privacy officer', parts: [{ type: 'p', text: 'The Center designates the following privacy officer to oversee personal-data processing and to handle complaints and remedies.' }, { type: 'officer' }] },
    { title: 'Remedies', parts: [{ type: 'p', text: 'To report an infringement or to seek advice, you may contact the following bodies in the Republic of Korea.' }, { type: 'ul', items: ['Personal Information Dispute Mediation Committee: 1833-6972 (www.kopico.go.kr)', 'Personal Information Infringement Report Center: 118, no area code (privacy.kisa.or.kr)', 'Supreme Prosecutors’ Office: 1301, no area code (www.spo.go.kr)', 'Korean National Police Agency: 182, no area code (ecrm.police.go.kr)'] }] },
    { title: 'Changes to this policy', parts: [{ type: 'p', text: 'This privacy policy applies from 28 September 2026.' }] },
  ],
  ['Processor (recipient)', 'Task', 'Country', 'Items transferred', 'When and how', 'Retention'],
  ['Vercel Inc.', 'Site hosting and transmission of the contact form', 'United States', 'Name, email, affiliation, message, access logs', 'Sent over the network when the form is submitted', 'Not stored after transmission (access logs follow the hosting log period)'],
  ['Google LLC', 'Sending the inquiry by email (Gmail)', 'United States', 'Name, email, affiliation, message', 'Sent over the network when the form is submitted', '1 year after the inquiry is resolved'],
  { officerName: 'Kim Seul-ong', officerRole: 'Director, Sejong Korean Language and Culture Center', labelName: 'Name', labelPhone: 'Phone', labelEmail: 'Email' },
)

